param([string]$EnvFile='.\.env')
$ErrorActionPreference='Stop';$v=@{};Get-Content $EnvFile|Where-Object{$_-match'^[^#].*='}|ForEach-Object{$p=$_-split'=',2;$v[$p[0].Trim()]=$p[1].Trim()};foreach($n in @('GK_SITE_URL','GK_SITE_AUDIT_TOKEN','GK_UNIFIED_API_TOKEN')){if([string]::IsNullOrWhiteSpace($v[$n])){throw"$n fehlt."}};$site=$v.GK_SITE_URL.TrimEnd('/');$ah=@{Authorization='Bearer '+$v.GK_SITE_AUDIT_TOKEN};$uh=@{Authorization='Bearer '+$v.GK_UNIFIED_API_TOKEN};$items=@();$page=1
do{$b=@(Invoke-RestMethod($site+'/wp-json/gk-site-audit/v1/items?page='+$page+'&per_page=100')-Headers $ah);if($b.Count-eq1-and$null-ne$b[0].items){$b=@($b[0].items)};$items+=$b;$page++}while($b.Count-eq100)
$links=@();foreach($i in ($items|Sort-Object{[long]$_.id}-Unique)){$id=[long]$i.id;$body=[Text.Encoding]::UTF8.GetBytes((@{id=$id}|ConvertTo-Json -Compress));$p=Invoke-RestMethod($site+'/wp-json/gk-unified-api/v1/read-post')-Method Post -Headers $uh -ContentType 'application/json; charset=utf-8' -Body $body;$html=[string]$p.content;$sections=@([regex]::Matches($html,'(?is)<h2\b[^>]*>\s*Weiterf.hrende Artikel\s*</h2>(?<body>.*?)(?=<h2\b|\z)')|ForEach-Object{$_.Groups.body.Value});$sections+=@([regex]::Matches($html,'(?is)<!--\s*GK_RELATED_START\s*-->(?<body>.*?)<!--\s*GK_RELATED_END\s*-->')|ForEach-Object{$_.Groups.body.Value});foreach($s in $sections){foreach($a in [regex]::Matches($s,'(?is)<a\b[^>]*href\s*=\s*["''](?<u>[^"'']+)["''][^>]*>(?<t>.*?)</a>')){$u=[Net.WebUtility]::HtmlDecode($a.Groups.u.Value);if($u.StartsWith('/') ){$u=$site+$u};if($u.StartsWith($site,[StringComparison]::OrdinalIgnoreCase)){$text=(([Net.WebUtility]::HtmlDecode([regex]::Replace($a.Groups.t.Value,'<[^>]+>',' ')))-replace'\s+',' ').Trim();$links+=[pscustomobject]@{source_id=$id;source_title=[string]$p.title;anchor_text=$text;url=$u}}}}}
$targetCache=@{};$rows=@();foreach($l in $links){if(-not $targetCache.ContainsKey($l.url)){try{$r=Invoke-WebRequest $l.url -UseBasicParsing -MaximumRedirection 5 -TimeoutSec 30;$raw=[string]$r.Content;$tm=[regex]::Match($raw,'(?is)<title[^>]*>(?<t>.*?)</title>');$title=(([Net.WebUtility]::HtmlDecode($tm.Groups.t.Value))-replace'\s+',' ').Trim();$main=[regex]::Replace($raw,'(?is)<script\b.*?</script>|<style\b.*?</style>|<[^>]+>',' ');$chars=(([Net.WebUtility]::HtmlDecode($main))-replace'\s+',' ').Trim().Length;$targetCache[$l.url]=[pscustomobject]@{http=[int]$r.StatusCode;final=$r.BaseResponse.ResponseUri.AbsoluteUri;target_title=$title;visible_chars=$chars}}catch{$code=0;if($_.Exception.Response){$code=[int]$_.Exception.Response.StatusCode};$targetCache[$l.url]=[pscustomobject]@{http=$code;final='';target_title='';visible_chars=0}}};$t=$targetCache[$l.url];$generic=$l.anchor_text-match'^(hier|mehr|mehr erfahren|weiter|weiterlesen|zum artikel|lesen)$';$rows+=[pscustomobject]@{source_id=$l.source_id;source_title=$l.source_title;anchor_text=$l.anchor_text;url=$l.url;http=$t.http;final_url=$t.final;target_title=$t.target_title;visible_chars=$t.visible_chars;generic_anchor=$generic;problem=($t.http-ne200-or$t.visible_chars-lt500-or$generic)}}
$root=if(Test-Path(Join-Path $PSScriptRoot '..\GkProductionWorker.sln')){Split-Path -Parent $PSScriptRoot}else{$PSScriptRoot};$dir=Join-Path $root 'reports';New-Item $dir -ItemType Directory -Force|Out-Null;$stamp=Get-Date -Format'yyyyMMdd-HHmmss';$rows|Export-Csv (Join-Path $dir('related-links-'+$stamp+'.csv')) -NoTypeInformation -Encoding UTF8;Write-Host('FERTIG: Links='+$rows.Count+' | Quellen='+@($rows|Select-Object source_id -Unique).Count+' | Probleme='+@($rows|Where-Object problem).Count)
